        p = len(colors)
        if not p:
            continue

        best_run = []
        run = []
        for v in row:
            if v != 0 and v != 4:
                run.append(v)
            else:
                if len(run) > len(best_run):
                    best_run = run
                run = []
        if len(run) > len(best_run):
            best_run = run

        # A direct lookup by column residue, using the longest visible run.
        start = max((i for i in range(w - len(best_run) + 1)
                     if list(row[i:i + len(best_run)]) == best_run), default=0)
        phase_values = {}
